from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    NotificationMsg, NotificationGroup, NotificationType, AttachmentType)


class PmUploadNotification(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(PmUploadNotification, self).__init__(*args, **kwargs)

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(soap, NotificationType.TransferNotification)
                and soap.notification_type == 'ne3s_pm_uploadNotification'
                and isinstance(attachment, AttachmentType.Omes)
                and soap.attachment_properties.compression == 'gzip')


class PmUploadEmptyNotification(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(PmUploadEmptyNotification, self).__init__(*args, **kwargs)

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(soap, NotificationType.TransferNotification)
                and soap.notification_type == 'ne3s_pm_queue_empty_notif')


class PMNotificationGroup(NotificationGroup):
    QUEUE_IDS = ("pm_queue", )
    NOTIFICATIONS = (PmUploadNotification, PmUploadEmptyNotification)
